using System.Text; using HelpDeskPro.Api.Data; using Microsoft.AspNetCore.Authorization; using Microsoft.AspNetCore.Mvc; using Microsoft.EntityFrameworkCore;
namespace HelpDeskPro.Api.Controllers; [ApiController][Route("api/exports")][Authorize(Roles="Admin,Support")]
public class ExportsController:ControllerBase {readonly AppDbContext db;public ExportsController(AppDbContext db){this.db=db;}[HttpGet("tickets.csv")] public async Task<IActionResult> Tickets(){var rows=await db.Tickets.Include(x=>x.Department).ToListAsync();var sb=new StringBuilder("Id,Title,Status,Priority,Department,CreatedAt,SlaDueAt,ResolvedAt,Rating\n");foreach(var x in rows)sb.AppendLine($"{x.Id},\"{x.Title.Replace("\"","\"\"")}\",{x.Status},{x.Priority},\"{x.Department?.Name}\",{x.CreatedAt:o},{x.SlaDueAt:o},{x.ResolvedAt:o},{x.Rating}");return File(Encoding.UTF8.GetBytes(sb.ToString()),"text/csv","helpdesk-tickets.csv");}}
